declare(strict_types=1); require_once __DIR__.'/../shared/response.php'; require_once __DIR__.'/../shared/request.php'; require_once __DIR__.'/../shared/auth.php'; methodOnly('POST'); requireAdmin(); safeApi(function():void{$db=apiDatabase();$i=jsonRequest();$title=inputString($i,'title',true);$code=inputString($i,'code',true);$type=$i['discount_type']??'';$allowed=['PERCENTAGE','FIXED','FREE_SHIPPING'];if(!in_array($type,$allowed,true))jsonResponse(false,'Invalid discount type.',null,[],422);$s=$db->prepare('INSERT INTO offers(title,code,discount_type,discount_value,min_order_amount,start_date,end_date,status) VALUES(:title,:code,:type,:value,:minimum,:start,:end,:status)');$s->execute([':title'=>$title,':code'=>$code,':type'=>$type,':value'=>(float)($i['discount_value']??0),':minimum'=>(float)($i['min_order_amount']??0),':start'=>$i['start_date']??null,':end'=>$i['end_date']??null,':status'=>$i['status']??'ACTIVE']);jsonResponse(true,'Offer created successfully.',['id'=>(int)$db->lastInsertId()],[],201);});
